-- IPA 2020-06-14 Q41–52: reviewed adaptations; q41, q46 and q52 link to 2019 repeats; graph and table represented as text.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20200614-q42','exam-fe','TLSクライアント認証','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問42・改編】利用者PCからDMZ内のWebサイトへ接続して個人情報を入力し、内部ネットワークのDBサーバに保存するシステムがある。利用者個人のディジタル証明書を用いてPCとWebサーバ間でTLS通信を行うとき期待できる効果はどれか。','[{"id":"a","text":"PCとDBサーバ間を暗号化しDBサーバの正当性を検証できる"},{"id":"b","text":"PCとDBサーバ間を暗号化し利用者を認証できる"},{"id":"c","text":"PCとWebサーバ間を暗号化しDBサーバの正当性を検証できる"},{"id":"d","text":"PCとWebサーバ間を暗号化し利用者を認証できる"}]','"d"','TLSで保護するのはPCとWebサーバ間の通信。利用者の証明書によってクライアント認証を行える。WebとDB間は別途保護が必要。中文：TLS保护PC与Web服务器之间的通信，客户端证书用于认证用户；Web与数据库之间需另行保护。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q43','exam-fe','サンドボックス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問43・改編】情報セキュリティにおけるサンドボックスの説明はどれか。','[{"id":"a","text":"様々なソフトウェアや機器の大量ログを分析する"},{"id":"b","text":"入力中のHTMLやSQLなどを別の文字列に置き換える"},{"id":"c","text":"Webサーバの前段で不特定多数からのリクエストに代理応答する"},{"id":"d","text":"不正動作のおそれがあるプログラムを特別な領域で動作させ、他への悪影響を防ぐ"}]','"d"','隔離された環境でプログラムを実行し影響を制限する。中文：沙箱在隔离环境中运行程序，限制其对其他区域的影响。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q44','exam-fe','パケットフィルタリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問44・改編】パケットフィルタリング型ファイアウォールが通過可否の判断に用いるものはどれか。','[{"id":"a","text":"Webアプリケーションに渡されるPOSTデータ"},{"id":"b","text":"送信元と宛先のIPアドレス及びポート番号"},{"id":"c","text":"送信元MACアドレス"},{"id":"d","text":"利用者のPCから送信されたURL"}]','"b"','パケットフィルタリングはIPアドレス、ポート番号、プロトコルなどのヘッダ情報を基に判定する。中文：包过滤通常依据源与目标IP、端口和协议等报头信息判断。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q45','exam-fe','オブジェクト指向の委譲','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問45・改編】オブジェクト指向における委譲の説明はどれか。','[{"id":"a","text":"ある操作が関連するオブジェクトにも自動適用される仕組み"},{"id":"b","text":"あるオブジェクトへの操作を内部で他のオブジェクトに依頼する仕組み"},{"id":"c","text":"下位クラスが上位クラスの属性や操作を引き継ぐ仕組み"},{"id":"d","text":"複数のオブジェクトを部分として新しいオブジェクトを生成する仕組み"}]','"b"','委譲は処理を別のオブジェクトに任せること。継承はクラス間で属性や操作を引き継ぐ。中文：委托是将处理交给另一个对象；继承则是类之间继承属性或方法。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q47','exam-fe','バグ累積曲線','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問47・改編】横軸をテスト項目消化件数、縦軸をバグ累積件数とするグラフがある。曲線は原点から右上がりで、後半ほど傾きが大きくなり、消化件数Xで設定した累積バグ件数の目標に到達した。この状況の説明として適切なものはどれか。','[{"id":"a","text":"テスト工程が順調に終了したことを示す"},{"id":"b","text":"テスト前の机上チェックやシミュレーションが十分だったことを示す"},{"id":"c","text":"まだ多くのバグが内在している可能性を示す"},{"id":"d","text":"目標に到達したので出荷後のバグ発生確率が低いことを示す"}]','"c"','終盤で発見ペースが増加しており、目標件数への到達だけでは品質収束を示さない。未発見バグが多い可能性がある。中文：后期发现速度仍在增加，达到目标数量并不代表质量已收敛，可能仍有大量缺陷。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q48','exam-fe','ボトムアップテスト','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問48・改編】ボトムアップテストの特徴として適切なものはどれか。','[{"id":"a","text":"開発初期には並行作業が困難である"},{"id":"b","text":"スタブが必要である"},{"id":"c","text":"テスト済みの上位モジュールが必要である"},{"id":"d","text":"ドライバが必要である"}]','"d"','下位モジュールから試験するため、未完成の上位モジュールの代わりにドライバを使う。中文：自底向上测试时，用驱动程序模拟尚未完成的上位模块。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q49','exam-fe','リファクタリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問49・改編】アジャイル開発でも重視されるリファクタリングはどれか。','[{"id":"a","text":"2人のプログラマが協力して一つのプログラムを書く"},{"id":"b","text":"外部仕様を変えず内部構造を変更して保守性を高める"},{"id":"c","text":"テストケースを先に設定してから実装する"},{"id":"d","text":"利用者のフィードバックのため試作品を早期に作る"}]','"b"','外部から見える振る舞いを変えずコードの内部構造を改善する。中文：重构在保持外部行为不变的前提下改善代码结构。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q50','exam-fe','マッシュアップ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問50・改編】マッシュアップに該当するものはどれか。','[{"id":"a","text":"既存プログラムからその仕様を導き出す"},{"id":"b","text":"既存プログラムを部品化し組み合わせて新規プログラムを開発する"},{"id":"c","text":"クラスライブラリを利用して新規プログラムを開発する"},{"id":"d","text":"公開されている複数のサービスを利用して新たなサービスを提供する"}]','"d"','複数の公開サービスやAPIを組み合わせ、新しい価値を持つサービスを提供する。中文：Mashup组合多个公开服务或API，提供新的服务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200614-q51','exam-fe','画面作成工数見積り','standard','single_choice','【IPA 2020年度 修了認定試験 2020-06-14 問51・改編】100画面の作成工数を見積もる。小・単純30画面、中・普通40画面、大・普通20画面、大・複雑10画面。1画面当たりの人日は、小（単純0.4、普通0.6、複雑0.8）、中（単純0.6、普通0.9、複雑1.0）、大（単純0.8、普通1.0、複雑1.2）。全画面のレビュー・修正に5人日、作業管理にレビュー・修正を含む作業工数の20%を要する。総工数は何人日か。','[{"id":"a","text":"80"},{"id":"b","text":"85"},{"id":"c","text":"101"},{"id":"d","text":"102"}]','"d"','作成は30×0.4＋40×0.9＋20×1.0＋10×1.2＝80人日。レビュー・修正を加え85人日、管理20%を加えると85×1.2＝102人日。中文：制作80人日，加审查修正5人日，再加管理费20%，共102人日。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200614_FE.pdf','ja','A','explicit','standard','fe_exemption');
